def audit_logical_access_and_sod_conflicts(
    user_access_roster: list = None,
    hr_termination_records: list = None
) -> dict:
    # ITGC Domain 1: User Termination & SOD Conflict Detector
    if hr_termination_records is None:
        hr_termination_records = [
            {"emp_id": "EMP-104", "name": "David Vance", "term_date": "2026-03-15"},
            {"emp_id": "EMP-208", "name": "Sarah Jenkins", "term_date": "2026-06-30"}
        ]

    if user_access_roster is None:
        user_access_roster = [
            {"emp_id": "EMP-104", "name": "David Vance", "account_status": "ACTIVE", "roles": ["AP_CLERK"]}, # Terminated but active!
            {"emp_id": "EMP-208", "name": "Sarah Jenkins", "account_status": "LOCKED", "roles": ["AR_CLERK"]},
            {"emp_id": "EMP-305", "name": "Michael Scott", "account_status": "ACTIVE", "roles": ["VENDOR_MASTER_MAINTAIN", "AP_PAYMENT_RELEASE"]}, # Toxic SOD!
            {"emp_id": "EMP-412", "name": "Rachel Adams", "account_status": "ACTIVE", "roles": ["GL_ACCOUNTANT", "BANK_RECONCILER"]}
        ]

    termination_exceptions = []
    sod_conflicts_detected = []

    # 1. Termination Audit: Match active status against HR term dates
    term_dict = {t['emp_id']: t['term_date'] for t in hr_termination_records}
    for u in user_access_roster:
        emp = u['emp_id']
        if emp in term_dict and u['account_status'] == "ACTIVE":
            termination_exceptions.append({
                'employee': u['name'],
                'id': emp,
                'terminated_on': term_dict[emp],
                'system_status': "ACTIVE_UNAUTHORIZED_ACCESS_DEFICIENCY"
            })

        # 2. SOD Toxic Combination Rule Check
        roles = u['roles']
        # Toxic rule: Vendor Master + Payment Release
        if "VENDOR_MASTER_MAINTAIN" in roles and "AP_PAYMENT_RELEASE" in roles:
            sod_conflicts_detected.append({
                'employee': u['name'],
                'id': emp,
                'conflict_type': "TOXIC_SOD_VENDOR_CREATION_AND_PAYMENT",
                'risk': "FICTITIOUS_VENDOR_PAYMENT_FRAUD_EXPOSURE"
            })

    access_controls_effective = (len(termination_exceptions) == 0) and (len(sod_conflicts_detected) == 0)

    return {
        'total_users_scanned': len(user_access_roster),
        'termination_deficiencies_count': len(termination_exceptions),
        'sod_conflicts_count': len(sod_conflicts_detected),
        'logical_access_effective': access_controls_effective,
        'domain_1_audit_verdict': "ACCESS_CONTROLS_OPERATING_EFFECTIVELY" if access_controls_effective else "DEFICIENT_LOGICAL_ACCESS_AND_SOD_EXPOSURES",
        'termination_exceptions': termination_exceptions,
        'sod_conflicts': sod_conflicts_detected
    }

access_audit = audit_logical_access_and_sod_conflicts()
print("=== ITGC Domain 1: Logical Access & SOD Audit Report ===")
print(f"Users Scanned:               {access_audit['total_users_scanned']}")
print(f"Termination Exceptions:      {access_audit['termination_deficiencies_count']}")
print(f"Toxic SOD Conflicts:         {access_audit['sod_conflicts_count']}")
print(f"Logical Access Effective:    {access_audit['logical_access_effective']}")
print(f"Domain 1 Audit Verdict:      {access_audit['domain_1_audit_verdict']}")
print("\nDetailed Control Exceptions:")
for ex in access_audit['termination_exceptions']:
    print(f" - Terminated User Active: {ex['employee']:16} (ID: {ex['id']}) terminated {ex['terminated_on']} but remains ACTIVE!")
for sod in access_audit['sod_conflicts']:
    print(f" - Toxic SOD Combination:  {sod['employee']:16} has {sod['conflict_type']} -> Risk: {sod['risk']}")

def audit_program_change_management_pipeline(
    production_transports_list: list = None,
    approved_cab_tickets_list: list = None
) -> dict:
    # ITGC Domain 2: Change Management Transport Reconciliation Engine
    if approved_cab_tickets_list is None:
        approved_cab_tickets_list = [
            {"ticket_id": "CAB-2026-101", "authorized_migrator": "Release_Engineer_Bot", "uat_signed": True},
            {"ticket_id": "CAB-2026-102", "authorized_migrator": "Release_Engineer_Bot", "uat_signed": True},
            {"ticket_id": "CAB-2026-103", "authorized_migrator": "Release_Engineer_Bot", "uat_signed": False} # UAT missing!
        ]

    if production_transports_list is None:
        production_transports_list = [
            {"transport_id": "TR-SAP-901", "ticket_id": "CAB-2026-101", "migrated_by": "Release_Engineer_Bot", "is_developer": False},
            {"transport_id": "TR-SAP-902", "ticket_id": "CAB-2026-102", "migrated_by": "Release_Engineer_Bot", "is_developer": False},
            {"transport_id": "TR-SAP-903", "ticket_id": "CAB-2026-103", "migrated_by": "Release_Engineer_Bot", "is_developer": False},
            {"transport_id": "TR-SAP-904", "ticket_id": "NONE", "migrated_by": "Lead_Developer_Dan", "is_developer": True} # Direct-to-prod!
        ]

    ticket_dict = {t['ticket_id']: t for t in approved_cab_tickets_list}
    change_exceptions = []

    for tr in production_transports_list:
        tr_id = tr['transport_id']
        t_id = tr['ticket_id']
        migrator = tr['migrated_by']
        is_dev = tr['is_developer']

        # 1. Developer migration check (Absolute prohibition)
        if is_dev:
            change_exceptions.append({
                'transport': tr_id,
                'defect': "DEVELOPER_DIRECT_MIGRATION_TO_PRODUCTION",
                'details': f"Code deployed directly by developer '{migrator}' without segregation of duties."
            })
            continue

        # 2. CAB Approval Check
        if t_id not in ticket_dict:
            change_exceptions.append({
                'transport': tr_id,
                'defect': "UNAUTHORIZED_PRODUCTION_TRANSPORT",
                'details': f"Transport {tr_id} migrated without an approved CAB change ticket."
            })
        else:
            # 3. UAT Sign-off Check
            if not ticket_dict[t_id]['uat_signed']:
                change_exceptions.append({
                    'transport': tr_id,
                    'defect': "MISSING_UAT_BUSINESS_APPROVAL",
                    'details': f"Change ticket {t_id} lacked formal User Acceptance Testing sign-off."
                })

    changes_effective = len(change_exceptions) == 0

    return {
        'total_production_transports_audited': len(production_transports_list),
        'unauthorized_or_deficient_changes': len(change_exceptions),
        'change_management_effective': changes_effective,
        'domain_2_audit_verdict': "CHANGE_CONTROLS_OPERATING_EFFECTIVELY" if changes_effective else "CHANGE_MANAGEMENT_CONTROL_DEFICIENCIES_DETECTED",
        'exceptions_ledger': change_exceptions
    }

change_audit = audit_program_change_management_pipeline()
print("=== ITGC Domain 2: Program Change Management Audit Report ===")
print(f"Transports Audited:          {change_audit['total_production_transports_audited']}")
print(f"Deficient Transports:        {change_audit['unauthorized_or_deficient_changes']}")
print(f"Change Controls Effective:   {change_audit['change_management_effective']}")
print(f"Domain 2 Audit Verdict:      {change_audit['domain_2_audit_verdict']}")
print("\nDetailed Change Control Exceptions:")
for ex in change_audit['exceptions_ledger']:
    print(f" - [{ex['defect']}] Transport: {ex['transport']} -> {ex['details']}")
